solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <deque>
#include <string>
#include <vector>

struct Manifest { std::string name; int apiMajor; int apiMinor; std::vector<std::string> events; };

class PluginHost
{
public:
    PluginHost(int apiMajor, int apiMinor) : major{ apiMajor }, minor{ apiMinor } {}

    bool load(const Manifest& m)
    {
        if (m.apiMajor != major || m.apiMinor > minor) return false;
        for (const Plugin& p : plugins) if (lower(p.manifest.name) == lower(m.name)) return false;
        plugins.push_back({ m, true, {} });
        return true;
    }

    std::vector<std::string> route(const std::string& event) const
    {
        std::vector<std::string> out;
        for (const Plugin& p : plugins)
        {
            if (!p.enabled) continue;
            const auto& ev{ p.manifest.events };
            if (std::find(ev.begin(), ev.end(), event) != ev.end() || std::find(ev.begin(), ev.end(), "*") != ev.end())
                out.push_back(p.manifest.name);
        }
        return out;
    }

    bool reportTimeout(const std::string& plugin, std::uint64_t now)
    {
        for (Plugin& p : plugins)
        {
            if (p.manifest.name != plugin || !p.enabled) continue;
            p.timeouts.push_back(now);
            while (!p.timeouts.empty() && p.timeouts.front() + 60 < now) p.timeouts.pop_front();
            if (p.timeouts.size() >= 3) { p.enabled = false; return true; }
            return false;
        }
        return false;
    }

    std::vector<std::string> enabled() const
    {
        std::vector<std::string> out;
        for (const Plugin& p : plugins) if (p.enabled) out.push_back(p.manifest.name);
        return out;
    }

private:
    struct Plugin { Manifest manifest; bool enabled; std::deque<std::uint64_t> timeouts; };
    int major, minor;
    std::vector<Plugin> plugins;

    static std::string lower(std::string s)
    {
        for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return s;
    }
};

unitTests:
using S = std::vector<std::string>;
TEST("compatibility") {
    PluginHost host{ 2, 3 };
    CHECK(host.load({ "word-count", 2, 3, { "documentSaved" } }));
    CHECK(host.load({ "spell", 2, 0, { "documentChanged" } }));
    CHECK(!host.load({ "future", 2, 4, {} }));
    CHECK(!host.load({ "old", 1, 9, {} }));
    CHECK(!host.load({ "Word-Count", 2, 1, {} }));
    CHECK_EQ(host.enabled(), (S{ "word-count", "spell" }));
}
TEST("routing events") {
    PluginHost host{ 2, 3 };
    host.load({ "a", 2, 0, { "documentSaved", "selectionChanged" } });
    host.load({ "b", 2, 0, { "*" } });
    host.load({ "c", 2, 0, { "documentSaved" } });
    CHECK_EQ(host.route("documentSaved"), (S{ "a", "b", "c" }));
    CHECK_EQ(host.route("selectionChanged"), (S{ "a", "b" }));
    CHECK_EQ(host.route("themeChanged"), (S{ "b" }));
}
TEST("disabling a slow plugin") {
    PluginHost host{ 2, 3 };
    host.load({ "slow", 2, 0, { "*" } });
    host.load({ "fine", 2, 0, { "*" } });
    CHECK(!host.reportTimeout("slow", 0));
    CHECK(!host.reportTimeout("slow", 100));
    CHECK(!host.reportTimeout("slow", 130));
    CHECK(host.reportTimeout("slow", 150));
    CHECK_EQ(host.route("x"), (S{ "fine" }));
    CHECK(!host.reportTimeout("slow", 151));
    CHECK(!host.reportTimeout("ghost", 0));
    CHECK_EQ(host.enabled(), (S{ "fine" }));
}

